"""Fresh30 entries, prior orbit normal1x win, current attack/AI exact restore and native win."""
import argparse,asyncio,datetime,json
from playwright.async_api import async_playwright
from test_duel_browser import ROOT,FIELDS,snap,Pilot,Driver,begin,complete,load,watch
import test_orbit_browser as orbit
async def main(args):
 out=ROOT/args.out;out.parent.mkdir(parents=True,exist_ok=True);errors=[];bad=[];failed=[];report={'testedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'url':args.url,'entryPages':[]};pilot=await Pilot().start();oldpilot=await orbit.Pilot().start()
 def save():report.update(consoleErrors=errors,badResponses=bad,requestFailures=failed);out.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
 async with async_playwright() as pw:
  b=await pw.chromium.launch()
  try:
   ctx=await b.new_context(viewport={'width':1360,'height':1100});p=await ctx.new_page();watch(p,errors,bad,failed);base=args.url.rstrip('/')+'/'
   await p.goto(base);await p.locator('.lab-card').last.wait_for();await p.wait_for_load_state('networkidle');data=await p.evaluate('async()=>await(await fetch("./data/games.json")).json()');assert len(data['games'])==72 and len(data['groups'])==10 and len(data['experiments'])==30 and sum(e['levels'] for e in data['experiments'])==366 and data['version']=='2026.10.16.30';assert await p.locator('.lab-card .primary-link').count()==30;report['atlas']={'entries':72,'groups':10,'originals':30,'levels':366,'version':data['version']};save()
   for e in data['experiments']:
    r=await p.goto(base+e['url'].removeprefix('./'));await p.wait_for_load_state('networkidle');assert r.status==200 and await p.locator('h1').count()==1 and await p.locator('main').count()>=1 and await p.locator('script[type=module]').count()>=1,e['id'];report['entryPages'].append({'id':e['id'],'status':r.status,'title':await p.title()});save()
   await orbit.load(p,base+'games/orbit/');await orbit.begin(p);old,_,_=await orbit.complete(p,oldpilot);assert old['state']=='won' and old['lines']>=2 and old['remainingDust']==0;report['previousGame']={'id':'orbit','state':old['state'],'lines':old['lines'],'remainingDust':old['remainingDust'],'stats':old['stats'],'actualLog':old['log']};save()
   await load(p,base+'games/duel/');d=await Driver(p).start();await begin(p,d);partial,_,_=await complete(p,pilot,d,stop=lambda s:s['player']['action'] and s['player']['action']['kind']=='heavy' and s['player']['action']['age']>.05);assert partial['state']=='playing' and partial['player']['action'];await d.release();await p.keyboard.press('p');before=await snap(p);await load(p,base+'games/duel/',True);after=await snap(p);assert after['state']=='paused' and not after['held'] and after['accumulator']==0 and all(before[k]==after[k] for k in FIELDS);await p.wait_for_timeout(500);waited=await snap(p);assert all(waited[k]==after[k] for k in FIELDS);await p.locator('#resume').click();end,_,_=await complete(p,pilot,d);assert end['state']=='won' and end['player']['hp']>0 and end['enemy']['hp']==0;report['restoreAndWin']={'state':end['state'],'hp':end['player']['hp'],'score':end['score'],'exactFields':FIELDS,'restoredPlayer':after['player'],'restoredEnemy':after['enemy'],'stats':end['stats'],'actualLog':end['log']};save();await d.release();await ctx.close()
   ctx=await b.new_context(viewport={'width':390,'height':844},is_mobile=True,has_touch=True);p=await ctx.new_page();watch(p,errors,bad,failed);await load(p,base+'games/duel/');d=await Driver(p,True).start();await begin(p,d);end,_,_=await complete(p,pilot,d);assert end['state']=='won' and end['player']['hp']>0 and end['enemy']['hp']==0;report['nativeTouch']={'state':end['state'],'hp':end['player']['hp'],'score':end['score'],'stats':end['stats'],'actualLog':end['log'],'method':'Native tutorial/start/movement holds/directional guard holds/heavy taps at authored normal1x; scroll positioning helper only.'};await d.release();await ctx.close();assert not errors and not bad and not failed,(errors,bad,failed);report['passed']=True;save();print(json.dumps({'passed':True,'entryPages':len(report['entryPages']),'previousLines':report['previousGame']['lines'],'restoreHP':report['restoreAndWin']['hp'],'nativeHP':report['nativeTouch']['hp']}))
  except Exception as e:report['error']=type(e).__name__+': '+str(e)[:1800];raise
  finally:save();await b.close();await pilot.close();await oldpilot.close()
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('--url',default='https://yydshly.github.io/classic-games-atlas/');a.add_argument('--out',default='.local/duel-final-smoke.json');asyncio.run(main(a.parse_args()))
